PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry tanh_f32(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 n_elts
)
{
    .reg .pred  %p_done, %p_vec, %p1, %p2;
    .reg .s32   %r_tid, %r_bid, %r_bdim, %r_gdim, %idx, %stride, %i, %stride4, %tmp, %n;
    .reg .u64   %in, %out, %off, %addr_in, %addr_out;
    .reg .f32   %x0, %x1, %x2, %x3, %y0, %y1, %y2, %y3, %x, %y;
    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.s32 %n,   [n_elts];
    // Thread/block/grid info
    mov.u32  %r_tid,  %tid.x;
    mov.u32  %r_bid,  %ctaid.x;
    mov.u32  %r_bdim, %ntid.x;
    mov.u32  %r_gdim, %nctaid.x;
    // Linear thread index and stride
    mad.lo.s32 %idx, %r_bid, %r_bdim, %r_tid;
    mul.lo.s32 %stride, %r_gdim, %r_bdim;
    // Process 4 elements per iteration
    shl.b32 %i, %idx, 2;          // i = idx * 4
    shl.b32 %stride4, %stride, 2; // stride4 = stride * 4
LOOP:
    setp.ge.s32 %p_done, %i, %n;
    @%p_done bra DONE;
    // If we have at least 4 elements remaining, take the vector path
    add.s32 %tmp, %i, 3;
    setp.lt.s32 %p_vec, %tmp, %n;
    @%p_vec bra VEC4;
    // Scalar tail handling for 1-3 elements
    mul.wide.s32 %off, %i, 4;
    add.u64 %addr_in,  %in,  %off;
    add.u64 %addr_out, %out, %off;
    // First element (always valid here)
    ld.global.cs.f32 %x, [%addr_in];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr_out], %y;
    // Second element if (i+1) < n
    add.s32 %tmp, %i, 1;
    setp.lt.s32 %p1, %tmp, %n;
    @!%p1 bra NEXT_ITER;
    add.u64 %addr_in,  %addr_in,  4;
    add.u64 %addr_out, %addr_out, 4;
    ld.global.cs.f32 %x, [%addr_in];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr_out], %y;
    // Third element if (i+2) < n
    add.s32 %tmp, %i, 2;
    setp.lt.s32 %p2, %tmp, %n;
    @!%p2 bra NEXT_ITER;
    add.u64 %addr_in,  %addr_in,  4;
    add.u64 %addr_out, %addr_out, 4;
    ld.global.cs.f32 %x, [%addr_in];
    tanh.approx.f32 %y, %x;
    st.global.cs.f32 [%addr_out], %y;
    bra NEXT_ITER;
VEC4:
    mul.wide.s32 %off, %i, 4;
    add.u64 %addr_in,  %in,  %off;
    add.u64 %addr_out, %out, %off;
    ld.global.cs.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr_in];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.cs.v4.f32 [%addr_out], { %y0, %y1, %y2, %y3 };
NEXT_ITER:
    add.s32 %i, %i, %stride4;
